    },
    {
      "indicator": "MM50",
      "reading": "13.1768",
      "interpretation": "Média de médio prazo acima do preço; confirma estrutura baixista enquanto não for superada."
    },
    {
      "indicator": "MM200",
      "reading": "12.9377",
      "interpretation": "Referência de longo prazo acima do preço — ainda resistência relevante."
    },
    {
      "indicator": "EMA9",
      "reading": "11.7504",
      "interpretation": "EMA9 abaixo da EMA21 (11,75 < 12,17) e acima do preço — pressão vendedora de curto prazo."
    },
    {
      "indicator": "EMA21",
      "reading": "12.1662",
      "interpretation": "EMA21 confirmando tendência descendente de curto/médio prazo."
    },
    {
      "indicator": "MACD",
      "reading": "MACD -0.4664 / sinal -0.4616 / hist -0.0049",
      "interpretation": "MACD e linha de sinal negativos; histograma próximo de zero indica possível estabilização, porém momentum ainda vendedor."
    },
    {
      "indicator": "Bandas de Bollinger",
      "reading": "BB_lower 11.2217 / BB_mid 12.0870 / BB_upper 12.9523",
      "interpretation": "Fechamento próximo à banda inferior — condição de sobrevenda e maior volatilidade; bandas dilatadas após queda."
    },
    {
      "indicator": "RSI14",
      "reading": "27.2903",
      "interpretation": "RSI em sobrevenda (<30). Divergência altista recente (RSI mais alto enquanto preço fez mínima ligeiramente menor) aponta para possibilidade de repique de curto prazo."
    },
    {
      "indicator": "Volume",
      "reading": "9.8053489e+09 (02/12/2024); picos 3.04411251e+10 em 13/11",
      "interpretation": "Quedas acompanhadas por volumes elevados (confirmação vendedora); repiques com volume menor, baixa convicção dos compradores."
    }
  ]
}
